entries[239412] = { ["name"] = "Celumbra, the Night's Dichotomy", ["text"] = "2 sec cast\nReagents:\nBolt of Shadowcloth , Bolt of Starweave , Nethershard Essence , Blood of Sargeras (65), Imbued Silkweave (125), Sharp Spritethorn , Runic Catgut\nCraft Celumbra, the Night's Dichotomy.\nProfession Trainer:\nLegion Tailoring (100)\nCost:\n250\n\nCelumbra, the Night's Dichotomy\nBinds when equipped\nUnique-Equipped: Legion Legendary (1)Shoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 3 Critical Strike\n+ 4 Haste\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket\n\nDurability 120 / 120\nClasses: Priest , Mage , Warlock\nEquip: When an enemy is within 12 yards of you, you conceal yourself in the shadows, reducing damage taken by 5% and increasing movement speed by 10%. When no enemies are within 12 yards of you, Celumbra's starlight heals you for 1% of your maximum health every 1 sec.\n40\n\"Shadow and star, darkness and light, despair and hope.\"" }
entries[239413] = { ["name"] = "The Sentinel's Eternal Refuge", ["text"] = "2 sec cast\nReagents:\nWisp-Touched Elderhide , Nethershard Essence , Blood of Sargeras (65), Stonehide Leather (250)\nCraft The Sentinel's Eternal Refuge.\nProfession Trainer:\nLegion Leatherworking (100)\nCost:\n250\n\nThe Sentinel's Eternal Refuge\nBinds when equipped\nUnique-Equipped: Legion Legendary (1)Feet Leather\n5 Armor\n+4 [Agility or Intellect]+6 Stamina\n+ 3 Critical Strike\n+ 4 Mastery\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket\n\nDurability 95 / 95\nClasses: Rogue , Monk , Druid , Demon Hunter\nEquip: Each time you kill an enemy, you gain 5% movement speed for 1 min, stacking up to 5 times. At 5 stacks, while you are out of combat you turn into a Wisp, increasing your movement speed further and granting you the ability to fly.\n40\n\"Her spirit is bound within the leather of these treads, anchoring her to this world.\"" }
entries[239414] = { ["name"] = "Vigilance Perch", ["text"] = "2 sec cast\nReagents:\nPrime Wardenscale , Nethershard Essence , Blood of Sargeras (65), Stormscale (250)\nCraft Vigilance Perch.\nProfession Trainer:\nLegion Leatherworking (100)\nCost:\n250\n\nVigilance Perch\nBinds when equipped\nUnique-Equipped: Legion Legendary (1)Hands Mail\n7 Armor\n+4 [Agility or Intellect]+6 Stamina\n+ 3 Haste\n+ 4 Mastery\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket\n\nDurability 70 / 70\nClasses: Hunter , Shaman , Evoker\nEquip: Each time you kill an enemy, you gain 5% movement speed for 1 min, stacking up to 5 times. At 5 stacks, while you are out of combat you turn into a Spirit Owl, increasing your movement speed further and granting you the ability to fly.\n40\n\"Even in death, the spirits of the owls watch over their masters, so long as they have a steady glove to perch upon.\"" }
entries[239415] = { ["name"] = "Rethu's Incessant Courage", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nHammer of Forgotten Heroes , Nethershard Essence , Blood of Sargeras (65), Demonsteel Bar (125)\nCraft Rethu's Incessant Courage.\nProfession Trainer:\nLegion Blacksmithing (100)\nCost:\n250\n\nRethu's Incessant Courage\nBinds when equipped\nUnique-Equipped: Legion Legendary (1)Waist Plate\n10 Armor\n+4 [Strength or Intellect]+6 Stamina\n+ 4 Haste\n+ 3 Mastery\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket\n\nDurability 70 / 70\nClasses: Warrior , Paladin , Death Knight\nEquip: When an enemy is within 8 yards of you, you heal for 2% of your maximum health every 3 sec. When no enemies are within 8 yards of you, your movement speed is increased by 15%.\n40\n\"His bravery was contagious.\"" }
